import { SubjectType } from './Gamification';

export type ScanErrorType = 'network' | 'blurry' | 'not_a_problem' | 'unknown';
export class ScanError extends Error {
  constructor(public type: ScanErrorType, message: string) {
    super(message);
    this.name = 'ScanError';
  }
}
export interface SocraticStep {
  id: string;
  stepNumber: number;
  totalSteps: number;
  stepTitle: string;
  questionHeadline?: string;
  tutorExplanation?: string; // AI Tutorning chuqur, qadam-ba-qadam tushuntirishi (3-5 jumla)
  tutorQuestion: string;
  explanationSnippet: string;
  quickOptions: string[];
  optionSubtitles?: string[];
  correctOptionIndex: number;
  hintText: string;
  xpReward: number;
}

export interface SocraticProblemSession {
  id: string;
  subject: SubjectType;
  problemTitle: string;
  questionText?: string;
  equation: string;
  steps: SocraticStep[];
  finalAnswer: string;
  totalXpReward: number;
}

