/**
 * Pedagogical Math Formatter (Adheres strictly to school mathematical standards):
 * 1. Formats arithmetic division ('/' between numbers) as school division symbol ' : '
 * 2. Formats arithmetic multiplication ('*' between numbers) as school multiplication symbol ' × '
 * 3. Formats 4+ digit numbers with standard thousands separators (e.g. 1161 -> 1.161, 9288 -> 9.288, 8000 -> 8.000)
 */
export function formatEducationalMathText(text: string): string {
  if (!text) return '';
  let result = text;

  // 0. Strip LaTeX dollar markers ($ or $$) and convert common LaTeX symbols to Unicode
  result = result
    .replace(/\\times/g, '×')
    .replace(/\\div/g, ':')
    .replace(/\\cdot/g, '·')
    .replace(/\\approx/g, '≈')
    .replace(/\\le(q)?/g, '≤')
    .replace(/\\ge(q)?/g, '≥')
    .replace(/\\ne(q)?/g, '≠')
    .replace(/\$\$?/g, '');

  // 1. Replace division slash between numbers: e.g. "9288 / 8" -> "9288 : 8"
  result = result.replace(/(\d+)\s*\/\s*(\d+)/g, '$1 : $2');

  // 2. Replace multiplication asterisk between numbers: e.g. "12 * 8" -> "12 × 8"
  result = result.replace(/(\d+)\s*\*\s*(\d+)/g, '$1 × $2');

  // 3. Format 4+ digit numbers with dot thousand separator (1161 -> 1.161, 9288 -> 9.288)
  // Lookbehind (?<![\d.,]) ensures we don't match parts of existing formatted numbers or decimals
  // Lookahead (?!\.\d) ensures we don't re-match numbers already formatted or decimal parts
  result = result.replace(/(?<![\d.,])\b(\d{4,})\b(?!\.\d)/g, (match) => {
    return match.replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  });

  return result;
}

/**
 * Randomizes options for a Socratic step, formats math numbers/symbols according to pedagogical standards,
 * and recalculates correctOptionIndex so the correct answer is evenly distributed across A, B, and C.
 */
export function shuffleSocraticStep(step: SocraticStep): SocraticStep {
  if (!step.quickOptions || step.quickOptions.length <= 1) {
    return {
      ...step,
      stepTitle: formatEducationalMathText(step.stepTitle),
      tutorQuestion: formatEducationalMathText(step.tutorQuestion),
      hintText: formatEducationalMathText(step.hintText),
      quickOptions: (step.quickOptions || []).map((o) => formatEducationalMathText(o)),
    };
  }

  const rawCorrectIndex =
    typeof step.correctOptionIndex === 'number' &&
    step.correctOptionIndex >= 0 &&
    step.correctOptionIndex < step.quickOptions.length
      ? step.correctOptionIndex
      : 0;

  const pairs = step.quickOptions.map((opt, i) => ({
    text: formatEducationalMathText(opt),
    subtitle: step.optionSubtitles?.[i] ? formatEducationalMathText(step.optionSubtitles[i]) : undefined,
    isCorrect: i === rawCorrectIndex,
  }));

  // Fisher-Yates random shuffle
  for (let i = pairs.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [pairs[i], pairs[j]] = [pairs[j], pairs[i]];
  }

  const newCorrectIndex = pairs.findIndex((p) => p.isCorrect);

  return {
    ...step,
    stepTitle: formatEducationalMathText(step.stepTitle),
    questionHeadline: step.questionHeadline ? formatEducationalMathText(step.questionHeadline) : undefined,
    tutorExplanation: step.tutorExplanation ? formatEducationalMathText(step.tutorExplanation) : undefined,
    tutorQuestion: formatEducationalMathText(step.tutorQuestion),
    explanationSnippet: formatEducationalMathText(step.explanationSnippet || ''),
    hintText: formatEducationalMathText(step.hintText),
    quickOptions: pairs.map((p) => p.text),
    optionSubtitles: step.optionSubtitles ? pairs.map((p) => p.subtitle || '') : undefined,
    correctOptionIndex: newCorrectIndex >= 0 ? newCorrectIndex : 0,
  };
}

/**
 * Intelligently and universally separates full problem content into an instruction/question prompt
 * and a standalone mathematical formula or number sequence.
 * 
 * Works universally across:
 * - Math sequences: "Tushirib qoldirilgan sonlarni yozing: 10, 20, 30, _, 50..."
 * - Algebraic equations: "Tenglamani yeching: 5x - 20 = 2x + 12"
 * - Story word problems (Matnli masalalar)
 * - Physics / Chemistry problems with given conditions
 */
export function separateProblemContent(
  rawEquation?: string,
  explicitQuestionText?: string
): { instruction?: string; equation: string } {
  if (explicitQuestionText && explicitQuestionText.trim().length > 0) {
    return {
      instruction: formatEducationalMathText(explicitQuestionText.trim()),
      equation: formatEducationalMathText(rawEquation?.trim() || ''),
    };
  }

  if (!rawEquation) {
    return { equation: '' };
  }

  const trimmed = rawEquation.trim();

  // 1. If contains newline separating instruction and equation
  if (trimmed.includes('\n')) {
    const lines = trimmed.split('\n').map((l) => l.trim()).filter(Boolean);
    if (lines.length > 1) {
      return {
        instruction: formatEducationalMathText(lines[0]),
        equation: formatEducationalMathText(lines.slice(1).join(' ')),
      };
    }
  }

  // 2. If contains colon separating introductory sentence from math expression
  // e.g., "Tushirib qoldirilgan sonlarni yozing: 10, 20, 30..."
  const colonMatch = trimmed.match(/^([^:=]+:)\s*(.+)$/);
  if (colonMatch && /[a-zA-Zа-яА-Яo'g'shch]{3,}/i.test(colonMatch[1])) {
    return {
      instruction: formatEducationalMathText(colonMatch[1].trim()),
      equation: formatEducationalMathText(colonMatch[2].trim()),
    };
  }

  // 3. If string starts with words followed by formula/numbers
  const wordPrefixMatch = trimmed.match(/^([a-zA-Zа-яА-Яo'g'shch\s]{6,}\b)\s*([0-9xXyYzZaAbBcCdDeEfF+\-*/:=_÷×·]{3,}.*)$/i);
  if (wordPrefixMatch && !wordPrefixMatch[1].includes('=')) {
    return {
      instruction: formatEducationalMathText(wordPrefixMatch[1].trim() + ':'),
      equation: formatEducationalMathText(wordPrefixMatch[2].trim()),
    };
  }

  return { equation: formatEducationalMathText(trimmed) };
}

/**
 * Shuffles all steps in a Socratic problem session and formats all math text.
 */
export function shuffleProblemSession(session: SocraticProblemSession): SocraticProblemSession {
  return {
    ...session,
    equation: formatEducationalMathText(session.equation),
    problemTitle: formatEducationalMathText(session.problemTitle),
    questionText: session.questionText ? formatEducationalMathText(session.questionText) : undefined,
    finalAnswer: formatEducationalMathText(session.finalAnswer),
    steps: session.steps.map((step) => shuffleSocraticStep(step)),
  };
}

export const getDemoSocraticSession = (subject: SubjectType = 'math'): SocraticProblemSession => {
  let session: SocraticProblemSession;
  switch (subject) {
    case 'physics':
      session = DEMO_PHYSICS_SESSION;
      break;
    case 'chemistry':
      session = DEMO_CHEMISTRY_SESSION;
      break;
    case 'math':
    default:
      session = DEMO_SOCRATIC_SESSION;
      break;
  }
  return shuffleProblemSession(session);
};

import { AppConfig } from '../../core/config';
import { SubjectType } from '../../domain/entities/Gamification';
import { SocraticPromptBuilder } from '../../domain/prompts/SocraticPromptBuilder';
import {
  SocraticProblemSession,
  SocraticStep,
  DEMO_SOCRATIC_SESSION,
  shuffleSocraticStep,
  shuffleProblemSession,
  formatEducationalMathText,
  getDemoSocraticSession,
  separateProblemContent,
} from '../../domain/entities/SocraticDialogue';
import { VoiceEvaluationResult } from '../../domain/entities/VoiceEvaluation';
import { ISocraticAiRepository } from '../../domain/repositories/ISocraticAiRepository';

interface GeminiStepPayload {
  stepNumber: number;
  stepTitle: string;
  tutorExplanation?: string;
  tutorQuestion: string;
  explanationSnippet?: string;
  quickOptions: string[];
  correctOptionIndex: number;
  hintText: string;
  xpReward?: number;
}

interface GeminiSocraticResponse {
  equation: string;
  problemTitle: string;
  questionText?: string;
  finalAnswer: string;
  steps: GeminiStepPayload[];
}

export class GeminiSocraticDataSource implements ISocraticAiRepository {
  private readonly apiKey: string;
  private readonly model: string;
  private readonly endpoint: string;

  private readonly candidateModels: string[];

  constructor() {
    this.apiKey = AppConfig.gemini.apiKey;
    this.model = AppConfig.gemini.model;
    this.endpoint = AppConfig.gemini.endpoint;
    this.candidateModels = [
      this.model,
      'gemini-3.7-flash',
    ];
  }

  private cleanBase64(rawBase64: string): string {
    if (rawBase64.includes(',')) {
      return rawBase64.split(',')[1];
    }
    return rawBase64.trim();
  }

  private async callGeminiWithModelFallback(
    payload: any,
    timeoutMs: number = 25000
  ): Promise<string | null> {
    for (const model of this.candidateModels) {
      const url = `${this.endpoint}/${model}:generateContent?key=${this.apiKey}`;
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

      try {
        const response = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
          signal: controller.signal,
        });

        clearTimeout(timeoutId);

        if (response.ok) {
          const json = await response.json();
          const text = json?.candidates?.[0]?.content?.parts?.[0]?.text;
          if (text) {
            return text;
          }
        } else {
          console.warn(`[GeminiSocraticDataSource] Model ${model} returned status ${response.status}`);
        }
      } catch (err: any) {
        clearTimeout(timeoutId);
        console.warn(`[GeminiSocraticDataSource] Model ${model} request failed:`, err?.message || err);
      }
    }

    return null;
  }

  private getSocraticJsonSchema() {
    return {
      type: 'OBJECT',
      properties: {
        isImageReadable: {
          type: 'BOOLEAN',
          description: 'Set to false if the image is too blurry, empty, or not a math/science problem. Set to true if legible.'
        },
        unreadableReason: {
          type: 'STRING',
          description: 'If isImageReadable is false, provide a short polite reason in Uzbek, e.g. "Rasm xira, iltimos qaytadan oling!"'
        },
        problemTitle: {
          type: 'STRING',
          description: 'Concise, child-friendly title of the topic (e.g. "O\'nliklar ketma-ketligi", "Chiziqli tenglamalar").',
        },
        questionText: {
          type: 'STRING',
          description: 'The exact textual instruction, question prompt, or word problem statement transcribed from the student\'s notebook/textbook (e.g. "Tushirib qoldirilgan sonlarni yozing:", "Tenglamani yeching:", or the full story problem text). NEVER omit or drop the question text!',
        },
        equation: {
          type: 'STRING',
          description: 'The mathematical expression, numbers sequence, equation, or formulas from the problem (e.g. "10, 20, 30, _, 50, 60, _, 80, 90", "5x - 20 = 2x + 12").',
        },
        finalAnswer: {
          type: 'STRING',
          description: 'The verified final correct answer with celebratory icon.',
        },
        steps: {
          type: 'ARRAY',
          description: '2 to 3 progressive Socratic steps leading the child to find the solution.',
          items: {
            type: 'OBJECT',
            properties: {
              stepNumber: { type: 'INTEGER' },
              stepTitle: { type: 'STRING', description: 'Short, clean title of this step (e.g. "Qavslarni ochish")' },
              tutorExplanation: {
                type: 'STRING',
                description: 'Deep, clear 3-5 sentence pedagogical explanation of the rule, why it applies, and the step-by-step logic, like an expert tutor explaining in a clean white notebook.',
              },
              tutorQuestion: {
                type: 'STRING',
                description: 'Gentle Socratic question directing the child to the first logical sub-step.',
              },
              explanationSnippet: {
                type: 'STRING',
                description: 'Helpful conceptual tip explaining the rule without solving it completely.',
              },
              quickOptions: {
                type: 'ARRAY',
                items: { type: 'STRING' },
                description: '3 interactive choices for the student: one correct next move, two common misconceptions.',
              },
              correctOptionIndex: {
                type: 'INTEGER',
                description: '0-based index of the correct option in quickOptions array.',
              },
              hintText: {
                type: 'STRING',
                description: 'Encouraging hint if the child gets stuck.',
              },
              xpReward: { type: 'INTEGER' },
            },
            required: [
              'stepNumber',
              'stepTitle',
              'tutorExplanation',
              'tutorQuestion',
              'quickOptions',
              'correctOptionIndex',
              'hintText',
            ],
          },
        },
      },
      required: ['equation', 'problemTitle', 'finalAnswer', 'steps'],
    };
  }

  async analyzeNotebookImage(
    base64Image: string,
    subject: SubjectType
  ): Promise<SocraticProblemSession> {
    try {
      const cleanData = this.cleanBase64(base64Image);

      const systemPrompt = SocraticPromptBuilder.buildSystemPrompt(subject);

      const payload = {
        systemInstruction: { parts: [{ text: systemPrompt }] },
        contents: [
          {
            parts: [
              {
                inlineData: {
                  mimeType: 'image/jpeg',
                  data: cleanData,
                },
              },
              {
                text: "Please read this student's notebook or screen carefully and transcribe the math/science problem verbatim. If the image is extremely blurry, cut off, or not related to a subject, set isImageReadable to false and explain why. Otherwise, set it to true and provide the pedagogical Socratic breakdown.",
              },
            ],
          },
        ],
        generationConfig: {
          responseMimeType: 'application/json',
          responseSchema: this.getSocraticJsonSchema(),
          temperature: 0.2,
        },
      };

      const rawText = await this.callGeminiWithModelFallback(payload, 25000);

      if (!rawText) {
        throw new ScanError('network', "Internet ulanishida muammo bor. Wi-Fi ni tekshirib ko'r!");
      }

      const parsedData: GeminiSocraticResponse = JSON.parse(rawText);
      if (parsedData.isImageReadable === false) {
        throw new ScanError('blurry', parsedData.unreadableReason || "Rasm biroz xira chiqdi \uD83D\uDE05 Qani, yana bir marta urinamiz!");
      }
      return this.transformToDomainSession(parsedData, subject);
    } catch (error) {
      console.error('[GeminiSocraticDataSource] Vision analysis failed:', error);
      if (error && typeof error === 'object' && 'name' in error && (error as Error).name === 'ScanError') {
        throw error as ScanError;
      }
      throw new ScanError('unknown', "Tahlil qilishda noma'lum xatolik yuz berdi.");
    }
  }

  async generateSocraticFromText(
    problemText: string,
    subject: SubjectType
  ): Promise<SocraticProblemSession> {
    try {
      const systemPrompt = SocraticPromptBuilder.buildSystemPrompt(subject);
      const prompt = `Here is the student's typed text problem:\n"${problemText}"\n`;

      const payload = {
        systemInstruction: { parts: [{ text: systemPrompt }] },
        contents: [{ parts: [{ text: prompt }] }],
        generationConfig: {
          responseMimeType: 'application/json',
          responseSchema: this.getSocraticJsonSchema(),
          temperature: 0.2,
        },
      };

      const rawText = await this.callGeminiWithModelFallback(payload, 15000);

      if (!rawText) {
        throw new ScanError('network', "Internet ulanishida muammo bor. Wi-Fi ni tekshirib ko'r!");
      }

      const parsedData: GeminiSocraticResponse = JSON.parse(rawText);
      return this.transformToDomainSession(parsedData, subject);
    } catch (error) {
      console.error('[GeminiSocraticDataSource] Text analysis failed:', error);
      if (error && typeof error === 'object' && 'name' in error && (error as Error).name === 'ScanError') {
        throw error as ScanError;
      }
      throw new ScanError('unknown', "Tahlil qilishda noma'lum xatolik yuz berdi.");
    }
  }

  private transformToDomainSession(
    data: GeminiSocraticResponse,
    subject: SubjectType
  ): SocraticProblemSession {
    const totalSteps = data.steps.length;
    const domainSteps: SocraticStep[] = data.steps.map((s, idx) => {
      const stepTitleText = s.stepTitle || `${idx + 1}-qadam • Tahlil`;
      const rawStep: SocraticStep = {
        id: `step_${idx + 1}_${Date.now()}`,
        stepNumber: s.stepNumber || idx + 1,
        totalSteps,
        stepTitle: formatEducationalMathText(stepTitleText),
        questionHeadline: formatEducationalMathText(stepTitleText),
        tutorExplanation: s.tutorExplanation ? formatEducationalMathText(s.tutorExplanation) : undefined,
        tutorQuestion: formatEducationalMathText(s.tutorQuestion),
        explanationSnippet: s.explanationSnippet ? formatEducationalMathText(s.explanationSnippet) : "Asosiy qoidani eslaymiz.",
        quickOptions: s.quickOptions || ['Variant A', 'Variant B', 'Variant C'],
        correctOptionIndex: typeof s.correctOptionIndex === 'number' ? s.correctOptionIndex : 0,
        hintText: formatEducationalMathText(s.hintText || "Masalani kichikroq bo'laklarga ajratib ko'ring."),
        xpReward: s.xpReward || 25,
      };
      return shuffleSocraticStep(rawStep);
    });

    const { instruction, equation: separatedEquation } = separateProblemContent(
      data.equation,
      data.questionText
    );

    return {
      id: `session_${Date.now()}`,
      subject,
      equation: separatedEquation || formatEducationalMathText(data.equation || 'Daftardagi masala'),
      questionText: instruction,
      problemTitle: formatEducationalMathText(data.problemTitle || 'Sokratik Yechim'),
      steps: domainSteps,
      finalAnswer: formatEducationalMathText(data.finalAnswer || "Ajoyib! Masala to'liq yechildi!"),
      totalXpReward: domainSteps.reduce((acc, step) => acc + step.xpReward, 25),
    };
  }

}

