      animateBar(bar1, 0.3, 0.6, 420);
      animateBar(bar2, 0.35, 0.75, 380);
      animateBar(bar3, 0.4, 0.85, 450);
      animateBar(bar4, 0.3, 0.65, 400);
      animateBar(bar5, 0.25, 0.55, 430);
