          {subtitle ? (
            <RichMathText
              style={[
                choiceStyles.subtitleText,
                isCorrect && choiceStyles.subtitleTextCorrect,
                isSelected && !isCorrect && choiceStyles.subtitleTextSelected,
                isWrong && choiceStyles.subtitleTextWrong,
              ]}
            >
              {subtitle}
            </RichMathText>
          ) : null}
        </View>
      </Animated.View>
    </Pressable>
  );
